descriptor.controllerScript:
//Alias settings

// Required minimum 1 alias with the next keys:
// - floorplan (it can be any name/label, but it should be an decoded image on base64 format)
// - perimeter (polygone, only 4 dots)
// - pointA (attribute, can be null)
// - pointB (attribute, can be null)
// - pointC (attribute, can be null)

let attributeService, utils, settings;

self.onInit = function() {
    attributeService = self.ctx.$scope.$injector.get(self.ctx.servicesMap.get('attributeService'));
    utils = self.ctx.$scope.$injector.get(self.ctx.servicesMap.get('utils'));
    settings = utils.deepClone(self.ctx.settings) || {};
    self.ctx.broadcastService = self.ctx.$scope.$injector.get(self.ctx.servicesMap.get('broadcastService'));

    self.ctx.broadcastService.on('geofencesUpdate', (event, args) => {
        self.ctx.updateAliases();
        self.ctx.detectChanges();
    });

    self.ctx.$scope.alreadyDrowed = false;

    self.ctx.map = new TbMapWidgetV2('openstreet-map', false, self.ctx);

    self.ctx.$scope.saveCoordinates = function(){
        if(self.ctx.$scope.entityId){
            const fourthPoint = findFourthPoint(self.ctx.$scope.pointA,self.ctx.$scope.pointB,self.ctx.$scope.pointC);

            attributeService.saveEntityAttributes(self.ctx.$scope.entityId, 'SERVER_SCOPE',
                [{key: 'pointA', value: self.ctx.$scope.pointA}, 
                {key: 'pointB', value: self.ctx.$scope.pointB}, 
                {key: 'pointC', value: self.ctx.$scope.pointC}, 
                {key: 'perimeter', value: [
                    fourthPoint,
                    self.ctx.$scope.pointB,
                    self.ctx.$scope.pointA,
                    self.ctx.$scope.pointC
                ]}]).subscribe(() => {
                    self.ctx.broadcastService.broadcast('coordinatesSaved', 'Some data');
                    self.ctx.showSuccessToast("Coordinates were updated successfully!", 4000, "bottom", "left", "layout");
                });
        }
    };

    self.ctx.broadcastService.on('geofencesUpdate', (event, args) => {
        self.ctx.updateAliases();
        self.ctx.detectChanges();
    });

    var customControl = L.Control.extend({
        options: {
            position: 'topleft'
        },

        onAdd: function (map) {
            var container = L.DomUtil.create('div', 'leaflet-bar leaflet-control leaflet-control-custom');

            container.style.backgroundColor = 'white';
            container.style.width = '34px';
            container.style.height = '34px';
            container.style.cursor = 'pointer';
            container.title = 'Save'; 
            container.style.display = 'flex';
            container.style.alignItems = 'center';
            container.style.justifyContent = 'center';

            var icon = L.DomUtil.create('i', 'fa-solid fa-floppy-disk');
            container.appendChild(icon);

            container.onclick = function () {
                self.ctx.$scope.saveCoordinates();
            };

            return container;
        }
    });

    setTimeout(function() {
        if(settings.draggableImage && self.ctx.map.map.map){
            self.ctx.map.map.map.addControl(new customControl());
        }
    }, 0);


    self.ctx.$scope.floorplan;
    self.ctx.$scope.perimeter;
    self.ctx.$scope.pointA;
    self.ctx.$scope.pointB;
    self.ctx.$scope.pointC;
    self.ctx.$scope.layers = [];
    self.ctx.$scope.previousDatasources = self.ctx.$scope.previousDatasources || [];
};

self.onDataUpdated = function() {
    // console.log(self.ctx.map.map.map)

    // if(settings.draggableImage && self.ctx.map.map.map){
    //     self.ctx.map.map.map.addControl(new customControl());
    // }

    const currentDatasources = JSON.stringify(self.ctx.datasources); 
    const previousDatasources = JSON.stringify(self.ctx.$scope.previousDatasources);

    if(isDatasourcesChanged(currentDatasources, previousDatasources)){
        self.ctx.$scope.previousDatasources = JSON.parse(currentDatasources);
        if(self.ctx.$scope.layers.length>0){
            self.ctx.$scope.layers.forEach(x=>{
            	self.ctx.map.map.map.removeLayer(x); 
            });
        }
	    self.ctx.$scope.alreadyDrowed = false;
    } else {
        self.ctx.$scope.alreadyDrowed = true;
    }


    self.ctx.datasources.forEach(x=>{
        if(x.aliasName == settings.imageAlias){
            self.ctx.$scope.entityId = x.entity.id;
        }
    });

    self.ctx.data.forEach(x=>{
        if(x.dataKey.name == settings.imageKey){
            self.ctx.$scope.floorplan = x.data[0][1];         
        } else if(x.dataKey.label == settings.aliasPolygonKey){
            if(x.data[0][1] && JSON.parse(x.data[0][1])){
                self.ctx.$scope.perimeter = JSON.parse(x.data[0][1]);         
            }
        } else if(x.dataKey.name == "pointA"){
            if(x.data[0][1] && JSON.parse(x.data[0][1])){
                self.ctx.$scope.pointA = JSON.parse(x.data[0][1]);
            }
        } else if(x.dataKey.name == "pointB"){
            if(x.data[0][1] && JSON.parse(x.data[0][1])){
                self.ctx.$scope.pointB = JSON.parse(x.data[0][1]);
            }
        } else if(x.dataKey.name == "pointC"){
            if(x.data[0][1] && JSON.parse(x.data[0][1])){
                self.ctx.$scope.pointC = JSON.parse(x.data[0][1]);
            }
        }
    });


    if(!self.ctx.$scope.pointA && !self.ctx.$scope.pointB && !self.ctx.$scope.pointC){
        if(self.ctx.$scope.perimeter){
            self.ctx.$scope.pointA = self.ctx.$scope.perimeter[1];
            self.ctx.$scope.pointB = self.ctx.$scope.perimeter[0];
            self.ctx.$scope.pointC = self.ctx.$scope.perimeter[2];
        }
    }

    if(self.ctx.$scope.floorplan && self.ctx.$scope.pointA && self.ctx.$scope.pointB && self.ctx.$scope.pointC && !self.ctx.$scope.alreadyDrowed){
        var point1 = L.latLng(self.ctx.$scope.pointA[0], self.ctx.$scope.pointA[1]),
    	    point2 = L.latLng(self.ctx.$scope.pointB[0], self.ctx.$scope.pointB[1]), 
    	    point3 = L.latLng(self.ctx.$scope.pointC[0], self.ctx.$scope.pointC[1]);

    	let size = settings.draggableImage ? 20 : 1;

    	var editIcon = L.icon({
            iconUrl: iconImg,
            iconSize: [size, size]
        });

        var	marker1 = L.marker(point1, {draggable: settings.draggableImage, icon: editIcon} ).addTo(self.ctx.map.map.map),
    	    marker2 = L.marker(point2, {draggable: settings.draggableImage, icon: editIcon} ).addTo(self.ctx.map.map.map),
    	    marker3 = L.marker(point3, {draggable: settings.draggableImage, icon: editIcon} ).addTo(self.ctx.map.map.map);

    	var	bounds = new L.LatLngBounds(point1, point2).extend(point3);

    	self.ctx.map.map.map.fitBounds(bounds);

    	var overlay = L.imageOverlay.rotated(self.ctx.$scope.floorplan, point1, point2, point3, {
    		opacity: 0.8,
    		interactive: true
    	});

        function repositionImage() {
            self.ctx.broadcastService.broadcast('coordinatesChanged', 'Some data');

            self.ctx.$scope.pointA = Object.entries(marker1.getLatLng()).map(x=>x[1]);
    		self.ctx.$scope.pointB = Object.entries(marker2.getLatLng()).map(x=>x[1]);
    		self.ctx.$scope.pointC = Object.entries(marker3.getLatLng()).map(x=>x[1]);

    		overlay.reposition(marker1.getLatLng(), marker2.getLatLng(), marker3.getLatLng());
    	}

    	if(settings.draggableImage){
        	marker1.on('drag dragend', repositionImage);
        	marker2.on('drag dragend', repositionImage);
        	marker3.on('drag dragend', repositionImage);
    	}

    	self.ctx.map.map.map.addLayer(overlay);
    	self.ctx.$scope.layers.push(overlay);  
    	self.ctx.$scope.layers.push(marker1);
    	self.ctx.$scope.layers.push(marker2);
    	self.ctx.$scope.layers.push(marker3);

	    self.ctx.map.update();
	    self.ctx.$scope.alreadyDrowed = true;
    }

    self.ctx.map.update();
};

self.onResize = function() {
    self.ctx.map.resize();
};

function isDatasourcesChanged(currentDatasources, previousDatasources){
    return currentDatasources !== previousDatasources;
} 

self.actionSources = function() {
    return TbMapWidgetV2.actionSources();
};

self.onDestroy = function() {
    self.ctx.map.destroy();
};

function findFourthPoint(topleft, topright, bottomleft) {
    const bottomRight = [
        topright[0] - topleft[0] + bottomleft[0], 
        topright[1] - topleft[1] + bottomleft[1]
    ];

    return bottomRight;
}

self.typeParameters = function() {
    return {
        hasDataPageLink: true
    }
};

L.ImageOverlay.Rotated = L.ImageOverlay.extend({

	initialize: function (image, topleft, topright, bottomleft, options) {

		if (typeof(image) === 'string') {
			this._url = image;
		} else {
			this._rawImage = image;
		}

		this._topLeft    = L.latLng(topleft);
		this._topRight   = L.latLng(topright);
		this._bottomLeft = L.latLng(bottomleft);

		L.setOptions(this, options);
	},

	onAdd: function (map) {
		if (!this._image) {
			this._initImage();

			if (this.options.opacity < 1) {
				this._updateOpacity();
			}
		}

		if (this.options.interactive) {
			L.DomUtil.addClass(this._rawImage, 'leaflet-interactive');
			this.addInteractiveTarget(this._rawImage);
		}

		map.on('zoomend resetview', this._reset, this);

		this.getPane().appendChild(this._image);
		this._reset();
	},

    onRemove: function(map) {
        map.off('zoomend resetview', this._reset, this);
        L.ImageOverlay.prototype.onRemove.call(this, map);
    },

	_initImage: function () {
		var img = this._rawImage;
		if (this._url) {
			img = L.DomUtil.create('img');
			img.style.display = 'none';

			if (this.options.crossOrigin) {
				img.crossOrigin = '';
			}

			img.src = this._url;
			this._rawImage = img;
		}
		L.DomUtil.addClass(img, 'leaflet-image-layer');

		var div = this._image = L.DomUtil.create('div',
				'leaflet-image-layer ' + (this._zoomAnimated ? 'leaflet-zoom-animated' : ''));

		this._updateZIndex(); 

		div.appendChild(img);

		div.onselectstart = L.Util.falseFn;
		div.onmousemove = L.Util.falseFn;

		img.onload = function(){
			this._reset();
			img.style.display = 'block';
			this.fire('load');
		}.bind(this);

		img.alt = this.options.alt;
	},


	_reset: function () {
		var div = this._image;

		if (!this._map) {
			return;
		}

		var pxTopLeft    = this._map.latLngToLayerPoint(this._topLeft);
		var pxTopRight   = this._map.latLngToLayerPoint(this._topRight);
		var pxBottomLeft = this._map.latLngToLayerPoint(this._bottomLeft);
		var pxBottomRight = pxTopRight.subtract(pxTopLeft).add(pxBottomLeft);

		var pxBounds = L.bounds([pxTopLeft, pxTopRight, pxBottomLeft, pxBottomRight]);
		var size = pxBounds.getSize();
		var pxTopLeftInDiv = pxTopLeft.subtract(pxBounds.min);

		this._bounds = L.latLngBounds( this._map.layerPointToLatLng(pxBounds.min),
		                               this._map.layerPointToLatLng(pxBounds.max) );

		L.DomUtil.setPosition(div, pxBounds.min);

		div.style.width  = size.x + 'px';
		div.style.height = size.y + 'px';

		var imgW = this._rawImage.width;
		var imgH = this._rawImage.height;
		if (!imgW || !imgH) {
			return;
		}

		var vectorX = pxTopRight.subtract(pxTopLeft);
		var vectorY = pxBottomLeft.subtract(pxTopLeft);

		this._rawImage.style.transformOrigin = '0 0';
		this._rawImage.style.transform = "matrix(" +
			(vectorX.x/imgW) + ', ' + (vectorX.y/imgW) + ', ' +
			(vectorY.x/imgH) + ', ' + (vectorY.y/imgH) + ', ' +
			pxTopLeftInDiv.x + ', ' + pxTopLeftInDiv.y + ')';
	},


	reposition: function(topleft, topright, bottomleft) {
		this._topLeft    = L.latLng(topleft);
		this._topRight   = L.latLng(topright);
		this._bottomLeft = L.latLng(bottomleft);
		this._reset();
	},


	setUrl: function (url) {
		this._url = url;

		if (this._rawImage) {
			this._rawImage.src = url;
		}
		return this;
	}
});

let iconImg = "data:image/jpeg;base64,"

L.imageOverlay.rotated = function(imgSrc, topleft, topright, bottomleft, options) {
	return new L.ImageOverlay.Rotated(imgSrc, topleft, topright, bottomleft, options);
};

